import {joinText, localizedNumber, msg, uiText} from './i18n.mjs';
export function createWordReader({load,matches,fa,select,view,toast}){
 const $=id=>document.getElementById(id);let lexicon,roots,searchLimit=50,rootEntries=[],rootLimit=100,rootTicket=0;
 function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)uiText(e, text);if(cls)e.className=cls;return e;}
 async function init(){[lexicon,roots]=await Promise.all([load('kalemat/lexicon.json'),load('kalemat/roots.json')]);uiText($('words-total'), msg("word-reader.0_word_forms_and_meanings_1_roots", localizedNumber(lexicon.length), localizedNumber(roots.length)));search();}
 async function showRoot(id){const ticket=++rootTicket;view('words');uiText($('root-occurrences'), msg("word-reader.loading_root_occurrences"));const row=await load(`kalemat/roots/${id}.json`);if(ticket!==rootTicket)return;rootEntries=row.occurrences;rootLimit=100;uiText($('root-title'), msg("word-reader.root_0_1_occurrences_recorded", row.display||row.root, localizedNumber(rootEntries.length)));renderOccurrences();}
 function renderOccurrences(){const frag=document.createDocumentFragment();for(const row of rootEntries.slice(0,rootLimit)){const b=el('button',undefined,'word-occurrence');b.append(el('strong',row.arabic),el('span',row.meaning),el('small',msg("word-reader.surah_0_verse_1", localizedNumber(row.surah), localizedNumber(row.ayah))));b.onclick=()=>select(row.surah,row.ayah);frag.append(b);}$('root-occurrences').replaceChildren(frag);$('root-more').hidden=rootEntries.length<=rootLimit;}
 function search(){if(!lexicon)return;const query=$('words-search').value;const rows=lexicon.filter(w=>matches([w.arabic,w.meaning,w.root,w.rootDisplay].join(' '),query));uiText($('word-result-count'), msg("word-reader.0_results_showing_1", localizedNumber(rows.length), localizedNumber(Math.min(searchLimit,rows.length))));$('word-results').replaceChildren();for(const word of rows.slice(0,searchLimit)){const card=el('article',undefined,'word-card');card.append(el('h3',word.arabic),el('p',word.meaning));const root=el('button',msg("word-reader.root_0", word.rootDisplay||word.root));root.onclick=()=>showRoot(word.rootId).catch(e=>toast(e.message));const go=el('button',msg("word-reader.example_in_the_quran"));go.onclick=()=>select(word.firstOccurrence.surah,word.firstOccurrence.ayah);card.append(root,go);$('word-results').append(card);}$('words-more').hidden=rows.length<=searchLimit;}
 async function renderVerse(ayah){
 const [complete,selected]=await Promise.all([load(`full-words/surahs/${ayah.surah_id}.json`),load(`kalemat/surahs/${ayah.surah_id}.json`)]),v=complete.verses[ayah.number],node=el('div');
 node.append(el('p',msg("word-reader.meanings_are_presented_as_recorded_including_groups"),'footnote'));
 if(!v){node.append(el('p',msg("word-reader.no_vocabulary_data_available_for_this_verse"),'empty'));return node;}
 const grid=el('div',undefined,'word-grid');for(const group of v.groups){const card=el('article',undefined,'word-card');card.dataset.wordStart=group.start;card.dataset.wordLength=group.length;const title=el('h3',group.arabic);title.lang='ar';card.append(title,el('p',group.meaning));if(group.length>1)card.append(el('small',msg("word-reader.meaning_of_a_0_word_phrase", localizedNumber(group.length)),'footnote'));const wordRoots=[...new Set(v.words.slice(group.start,group.start+group.length).map(w=>w.root).filter(Boolean))];if(wordRoots.length)card.append(el('p',joinText(msg("word-reader.root"), " ", wordRoots.join('، ')),'footnote'));grid.append(card);}node.append(grid);
 const words=selected.verses[ayah.number]?.words||[];if(words.length){const details=el('details');details.append(el('summary',msg("word-reader.more_meanings_and_root_occurrences_in_the")));const extra=el('div',undefined,'word-grid');for(const w of words){const card=el('article',undefined,'word-card');card.append(el('h3',w.arabic),el('p',w.meaning));const root=el('button',msg("word-reader.occurrences_of_0", w.rootDisplay||w.root));root.onclick=()=>showRoot(w.rootId).catch(e=>toast(e.message));card.append(root);extra.append(card);}details.append(extra);node.append(details);}return node;
 }
 $('words-search').oninput=()=>{searchLimit=50;search()};$('words-more').onclick=()=>{searchLimit+=50;search()};$('root-more').onclick=()=>{rootLimit+=100;renderOccurrences()};
 return {init,renderVerse,showRoot};
}
